class Solution {
  public int minimumDistance(int[] nums) {
    int n = nums.length, best = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        if (nums[j] != nums[i]) continue;
        for (int k = j + 1; k < n; k++) {
          if (nums[k] == nums[i]) best = Math.min(best, 2 * (k - i));
        }
      }
    }
    return best == Integer.MAX_VALUE ? -1 : best;
  }
}
